-- One automatically published, reviewed-template poster per published session.
-- The session id and autoGenerated marker are stored in the immutable poster
-- data snapshot, keeping the index scoped to auto-created event posters.
CREATE UNIQUE INDEX posters_auto_session_unique_idx
  ON posters (instance_id, (data->>'sessionId'))
  WHERE data->>'autoGenerated'='true' AND data ? 'sessionId';
